      {
        "id": "john-1-1-3",
        "label": "John 1:1–3",
        "context": "The Word is distinguished from God and called God. Christian apologetics reads this alongside passages affirming one God and the personal distinction of Father and Son.",
        "verses": [
          {
            "number": 1,
            "text": "In the beginning was the Word, and the Word was with God, and the Word was God."
          },
          {
            "number": 2,
            "text": "The same was in the beginning with God."
          },
          {
            "number": 3,
            "text": "All things were made by him; and without him was not any thing made that was made."
